import {h,render,Component} from './vendor/preact.module.js';
import htm from './vendor/htm.module.js';
const html=htm.bind(h),get=p=>fetch(p,{cache:'no-store'}).then(async r=>r.ok?r.json():Promise.reject(new Error((await r.json().catch(()=>({}))).error||r.status))),json=s=>{try{return JSON.parse(s||'{}')}catch{return{}}};
class App extends Component{
 state={auth:null,data:{},draft:null,error:'',notice:''};
 componentDidMount(){get('/api/auth/state').then(auth=>{this.setState({auth});if(auth.logged_in)this.load()}).catch(()=>this.setState({auth:{logged_in:false}}))}
 load=()=>Promise.all(['links','devices','dns','lists','upnp','settings','trial'].map(async k=>[k,await get(`/api/${k==='trial'?'settings/trial':k}`).catch(()=>null)])).then(x=>this.setState({data:Object.fromEntries(x),error:''}));
 call=async(p,m,b)=>{const headers={'Content-Type':'application/json'};if(this.state.auth?.csrf)headers['X-CSRF-Token']=this.state.auth.csrf;const r=await fetch(p,{method:m,headers,body:b&&JSON.stringify(b)});if(!r.ok)throw new Error((await r.json().catch(()=>({}))).error||r.status);return r.json()};
 login=async e=>{e.preventDefault();try{this.setState({auth:await this.call('/api/auth/login','POST',{password:new FormData(e.currentTarget).get('password')})});this.load()}catch(x){this.setState({error:x.message})}};
 edit=(id,k,v)=>{const n=Number(v);if(!Number.isInteger(n)||n<0)return;const d=this.state.draft||json(this.state.data.settings?.overlay);d.links||={};d.links[id]={...(d.links[id]||{}),[k]:n};this.setState({draft:d,notice:''})};
 save=async()=>{try{const s=await this.call('/api/settings','PUT',{version:this.state.data.settings.version,overlay:this.state.draft});this.setState(x=>({data:{...x.data,settings:s},draft:null,notice:'Черновик сохранён; сеть пока не менялась.'}))}catch(x){this.setState({error:x.message});this.load()}};
 apply=async()=>{try{const trial=await this.call('/api/settings/trial','POST');this.setState(x=>({data:{...x.data,trial},notice:'Правила применены на 90 секунд. Проверьте связь и подтвердите.'}))}catch(x){this.setState({error:x.message})}};
 confirm=async()=>{try{await this.call('/api/settings/trial/confirm','POST');this.setState({notice:'Связь подтверждена.',draft:null});this.load()}catch(x){this.setState({error:x.message})}};
 logout=async()=>{await this.call('/api/auth/logout','POST');this.setState({auth:{logged_in:false},data:{}})};
 deviceSave=async(e,x)=>{e.preventDefault();const f=new FormData(e.currentTarget),edit={name:f.get('name'),type:f.get('type'),note:f.get('note')},dns=f.get('dns_mode'),upnp=f.get('upnp');if(dns)edit.dns_mode=dns;if(upnp)edit.upnp=upnp;try{await this.call(`/api/devices/${encodeURIComponent(x.id)}`,'PATCH',edit);this.setState({notice:'Устройство обновлено.'});this.load()}catch(err){this.setState({error:`Устройство не обновлено: ${err.message}`})}};
 forget=async id=>{if(!confirm('Забыть устройство? Его история и пользовательские настройки будут удалены.'))return;try{await this.call(`/api/devices/${encodeURIComponent(id)}`,'DELETE');this.setState({notice:'Устройство забыто.'});this.load()}catch(x){this.setState({error:`Устройство не удалено: ${x.message}`})}};
 deviceEditor=x=>html`<details class="card"><summary>${x.name||x.id} · ${x.online?'в сети':'не в сети'}</summary><form onSubmit=${e=>this.deviceSave(e,x)}><label>Имя<input name="name" value=${x.name}/></label><label>Тип<select name="type" value=${x.type||'other'}>${['phone','pc','tv','console','server','smart_home','other'].map(v=>html`<option value=${v}>${v}</option>`)}</select></label><label>Заметка<input name="note" value=${x.note||''}/></label><label>DNS<select name="dns_mode" disabled=${x.dns_mode_from==='config'} value=${x.dns_mode||''}><option value="">Не менять</option>${['observe','redirect','block','exempt'].map(v=>html`<option value=${v}>${v}</option>`)}</select></label><label>UPnP<select name="upnp" value=${x.upnp||''}><option value="">Не менять</option>${['deny','ask','allow'].map(v=>html`<option value=${v}>${v}</option>`)}</select></label><p><button>Сохранить устройство</button> <button type="button" class="danger" onClick=${()=>this.forget(x.id)}>Забыть</button></p>${x.dns_mode_from==='config'&&html`<p class="muted">DNS задан в конфигурации: меняется только через черновик правил.</p>`}</form></details>`;
 upnpResolve=async(id,decision)=>{try{await this.call(`/api/upnp/pending/${encodeURIComponent(id)}`,'POST',{decision});this.setState({notice:'Запрос UPnP обработан.'});this.load()}catch(x){this.setState({error:x.message})}};
 upnpClose=async x=>{if(!confirm(`Закрыть ${x.proto}/${x.ext_port}?`))return;try{await this.call(`/api/upnp/mappings/${x.proto}/${x.ext_port}`,'DELETE');this.setState({notice:'Проброс UPnP закрыт.'});this.load()}catch(err){this.setState({error:err.message})}};
 manualAdd=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body={domain:f.get('domain'),exact:f.get('exact')==='on',purpose:f.get('purpose')};if(body.purpose==='class')body.class=f.get('class');try{await this.call('/api/lists/manual','POST',body);this.setState({notice:'Доменное правило добавлено.'});e.currentTarget.reset();this.load()}catch(x){this.setState({error:x.message})}};
 manualDelete=async x=>{if(!confirm(`Удалить правило ${x.pattern}?`))return;try{await this.call(`/api/lists/manual?domain=${encodeURIComponent(x.pattern)}&match=${x.match}`,'DELETE');this.setState({notice:'Доменное правило удалено.'});this.load()}catch(err){this.setState({error:err.message})}};
 modifyDraft=change=>{const d=JSON.parse(JSON.stringify(this.state.draft||json(this.state.data.settings?.overlay)));change(d);this.setState({draft:d,notice:''})};
 addForward=e=>{e.preventDefault();const f=new FormData(e.currentTarget),next={name:f.get('name'),proto:f.get('proto'),port:f.get('port'),to:f.get('to'),to_port:Number(f.get('to_port'))||0,links:String(f.get('links')).split(',').map(x=>x.trim()).filter(Boolean)};this.modifyDraft(d=>{const active=json(this.state.data.settings?.active);d.forwards=[...(d.forwards||active.forwards||[]),next]});e.currentTarget.reset()};
 deleteForward=i=>{if(!confirm('Удалить ручной проброс из черновика?'))return;this.modifyDraft(d=>{const active=json(this.state.data.settings?.active),all=d.forwards||active.forwards||[];d.forwards=all.filter((_,n)=>n!==i)})};
 addClassRule=e=>{e.preventDefault();const f=new FormData(e.currentTarget),ports=String(f.get('ports')).split(',').map(x=>x.trim()).filter(Boolean),devices=String(f.get('devices')).split(',').map(x=>x.trim()).filter(Boolean),next={name:f.get('name'),class:f.get('class'),devices};if(f.get('proto'))next.proto=f.get('proto');if(ports.length)next.ports=ports;this.modifyDraft(d=>{const active=json(this.state.data.settings?.active);d.classify_rules=[...(d.classify_rules||active.classify_rules||[]),next]});e.currentTarget.reset()};
 deleteClassRule=i=>{if(!confirm('Удалить правило классификации из черновика?'))return;this.modifyDraft(d=>{const active=json(this.state.data.settings?.active),all=d.classify_rules||active.classify_rules||[];d.classify_rules=all.filter((_,n)=>n!==i)})};
 rulesEditor(active,draft){const forwards=draft.forwards||active.forwards||[],rules=draft.classify_rules||active.classify_rules||[],dev=this.state.data.devices?.devices||[];return html`<section class="card"><h2>Ручные пробросы</h2><p class="muted">Удаление требует подтверждения; изменение вступает в силу только после общего применения.</p>${forwards.map((x,i)=>html`<p>${x.name}: ${x.proto}/${x.port} → ${x.to}${x.to_port?':'+x.to_port:''} <button class="danger" onClick=${()=>this.deleteForward(i)}>Удалить</button></p>`)}<form onSubmit=${this.addForward}><label>Имя<input name="name" required placeholder="minecraft"/></label><label>Протокол<select name="proto"><option value="tcp">TCP</option><option value="udp">UDP</option><option value="both">TCP и UDP</option></select></label><label>Внешний порт<input name="port" required placeholder="25565 или 27015-27030"/></label><label>Устройство<select name="to" required>${dev.map(x=>html`<option value=${x.id}>${x.name||x.id}</option>`)}</select></label><label>Внутренний порт (0 = тот же)<input name="to_port" type="number" min="0"/></label><label>Каналы через запятую (пусто = все)<input name="links" placeholder="isp1, isp2"/></label><button>Добавить проброс</button></form></section><section class="card"><h2>Правила классификации</h2>${rules.map((x,i)=>html`<p>${x.name}: ${x.class} · ${(x.devices||[]).join(', ')||'все устройства'} <button class="danger" onClick=${()=>this.deleteClassRule(i)}>Удалить</button></p>`)}<form onSubmit=${this.addClassRule}><label>Имя<input name="name" required placeholder="pc-game"/></label><label>Класс<input name="class" required placeholder="gaming"/></label><label>Устройства (id/MAC/IP через запятую)<input name="devices" required placeholder="dev-aabbccddeeff"/></label><label>Протокол<select name="proto"><option value="">Любой</option><option value="tcp">TCP</option><option value="udp">UDP</option></select></label><label>Порты через запятую<input name="ports" placeholder="27015,27016-27030"/></label><button>Добавить правило</button></form></section>`}
 extras(){const u=this.state.data.upnp||{},l=this.state.data.lists||{},rules=l.manual||[];return html`<section class="card"><h2>UPnP</h2>${!u.enabled&&html`<p class="muted">UPnP выключен или недоступен.</p>`}${(u.pending||[]).map(p=>html`<article><p>${p.description||p.id}</p><button onClick=${()=>this.upnpResolve(p.id,'once')}>Разрешить разово</button> <button onClick=${()=>this.upnpResolve(p.id,'always')}>Разрешить всегда</button> <button class="danger" onClick=${()=>this.upnpResolve(p.id,'deny')}>Отклонить</button></article>`)}${(u.mappings||[]).map(x=>html`<p>${x.proto}/${x.ext_port} → ${x.addr}:${x.int_port} <button class="danger" onClick=${()=>this.upnpClose(x)}>Закрыть</button></p>`)}</section><section class="card"><h2>Ручные доменные правила</h2><form onSubmit=${this.manualAdd}><label>Домен<input name="domain" required placeholder="example.org"/></label><label>Назначение<select name="purpose"><option value="bypass">Обход</option><option value="never">Не обходить</option><option value="inside">Только внутри</option><option value="class">Класс</option></select></label><label>Класс (только для «Класс»)<input name="class" placeholder="gaming"/></label><label><input name="exact" type="checkbox"/> Только точное совпадение</label><button>Добавить правило</button></form>${rules.map(x=>html`<p>${x.pattern} · ${x.match} · ${x.purpose||x.class} <button class="danger" onClick=${()=>this.manualDelete(x)}>Удалить</button></p>`)}</section>`}
 editor(){const s=this.state.data.settings,t=this.state.data.trial;if(!s)return html`<p class="muted">Настройки недоступны.</p>`;const active=json(s.active),draft=this.state.draft||json(s.overlay);return html`<section class="card"><h2>Настройка каналов</h2><p class="muted">Общий черновик. Адрес LAN, имя Tross и доступ к API меняются только в файле на мини‑ПК.</p>${Object.entries(active.links||{}).map(([id,b])=>{const d=draft.links?.[id]||{};return html`<fieldset><legend>${id}</legend><label>Приоритет<input type="number" min="0" value=${d.priority??b.priority} onInput=${e=>this.edit(id,'priority',e.currentTarget.value)}/></label><label>Входящий канал, Мбит/с<input type="number" min="0" value=${d.down_mbit??b.down_mbit} onInput=${e=>this.edit(id,'down_mbit',e.currentTarget.value)}/></label><label>Исходящий канал, Мбит/с<input type="number" min="0" value=${d.up_mbit??b.up_mbit} onInput=${e=>this.edit(id,'up_mbit',e.currentTarget.value)}/></label></fieldset>`})}</section>${this.rulesEditor(active,draft)}<section class="card"><p><button disabled=${!this.state.draft} onClick=${this.save}>Сохранить общий черновик</button> <button disabled=${!!this.state.draft||!!t?.active} onClick=${this.apply}>Применить на 90 секунд</button> ${t?.active&&html`<button class="confirm" onClick=${this.confirm}>Связь сохранилась — подтвердить</button>`}</p>${t?.active&&html`<p class="warning">До ${new Date(t.expires_at).toLocaleTimeString()} прежние правила вернутся, если не подтвердить связь.</p>`}</section>`}
 render(){const {auth,data,error,notice}=this.state;if(!auth)return html`<p>Проверка входа…</p>`;if(!auth.logged_in)return html`<section class="card login"><h1>Tross</h1><form onSubmit=${this.login}><label>Пароль<input name="password" type="password" minlength="10" required autofocus/></label><button>Войти</button></form>${error&&html`<p class="error">${error}</p>`}</section>`;const links=data.links?.links||[],dev=data.devices?.devices||[];return html`<main class="content"><header class="top"><div><h1>Сеть дома</h1><span class="muted">спокойная техническая панель</span></div><button onClick=${this.logout}>Выйти</button></header><section class="card"><h2>Карта сети</h2><div class="grid"><article class="card node"><strong>Дом</strong><p>${dev.length} устройств</p></article><article class="card node"><strong>Tross</strong><p>работает</p></article><article class="card node"><strong>DNS</strong><p>${data.dns?.serving||'недоступен'}</p></article>${links.map(l=>html`<article class="card node"><strong>${l.name}</strong><p>${l.state}: ${l.rtt_ms.toFixed(1)} мс</p></article>`)}</div></section><section class="card"><h2>Устройства</h2>${dev.map(this.deviceEditor)}</section>${this.extras()}${this.editor()}${notice&&html`<p class="notice">${notice}</p>`}${error&&html`<p class="error">${error}</p>`}</main>`}
}
render(html`<${App}/>`,document.querySelector('#app'));
